  c1:{sky:'dusk',label:'山门',draw:(p,r,t)=>[moon(p,200,90,28,.9),mountains(p,r,{base:230,height:110,fill:t.far,op:.65,peaks:3,blur:1}),mountains(p,r,{base:290,height:100,fill:t.mid,peaks:5}),mist(p,270,.4),gate(640,350,2,t.near),pine(220,390,1.7,t.near),pine(1050,392,1.9,t.near),figure(560,382,1.7,{c:t.ink,hat:'scholar',scroll:true}),lantern(p,600,236,1.2),lantern(p,690,236,1.2)].join('')},
  c2:{sky:'night',label:'坊市',draw:(p,r,t)=>[stars(r,24),mountains(p,r,{base:200,height:80,fill:t.far,op:.5,peaks:3,blur:1}),hall(240,290,1.3,t.mid,true),hall(980,300,1.1,t.mid,true),mist(p,300,.3),...[120,330,540,760,980].map((x,i)=>stall(p,x,372,1.6,t.near,true)),...[200,420,640,860,1060].map((x,i)=>figure(x,384,1.3+i%2*.2,{c:t.ink,hat:i%2?'conical':null})),...[100,330,560,790,1020].map((x,i)=>lantern(p,x+40,150+(i%2)*14,.9))].join('')},
  c3:{sky:'pale',label:'药田',draw:(p,r,t)=>[sun(p,300,92,26),mountains(p,r,{base:230,height:90,fill:t.far,op:.6,peaks:3,blur:1}),`<rect y="250" width="${W}" height="150" fill="#2f2a1c" opacity=".92"/>`,field(r,262,9,'#8a7d4e',true),Array.from({length:18},(_,i)=>`<path d="M${60+i*65} 392 q-6 -26 ${(i%3-1)*6} -42" stroke="#6a5c34" stroke-width="2" fill="none"/>`).join(''),hall(980,282,1.1,t.near),`<path d="M930 292 h110 v8 h-110Z" fill="${t.near}"/>`,figure(500,372,1.7,{c:t.ink,hat:'conical',staff:true}),figure(600,378,1.4,{c:t.ink,sit:true}),`<path d="M120 330 l40 8 l30 -10 l40 12 M560 340 l60 6 l50 -8" stroke="#1a150c" stroke-width="2" fill="none" opacity=".7"/>`].join('')},
  c4:{sky:'storm',label:'试炼',draw:(p,r,t)=>[mountains(p,r,{base:220,height:180,fill:t.far,op:.8,peaks:3}),`<path d="M440 400 C520 300 560 220 600 90 C640 220 680 300 760 400Z" fill="${t.ink}" opacity=".85"/>`,rings(p,600,250,4,t.glow),`<circle cx="600" cy="250" r="22" fill="url(#${p}glow)"/>`,mist(p,320,.4),mountains(p,r,{base:372,height:70,fill:t.near,peaks:5}),figure(470,386,1.5,{c:t.ink,hat:'conical'}),figure(600,388,1.7,{c:t.ink,hat:'scholar',staff:true}),figure(740,386,1.5,{c:t.ink,cloak:true}),rain(r,50,.18)].join('')},
  c5:{sky:'storm',label:'夜路',draw:(p,r,t)=>[mountains(p,r,{base:230,height:90,fill:t.far,op:.5,peaks:3,blur:1}),`<path d="M0 400 L1200 400 L1200 340 Q600 300 0 350Z" fill="${t.near}"/>`,`<path d="M-20 392 Q500 340 1220 370" stroke="#4a5a4a" stroke-width="26" opacity=".25" fill="none" filter="url(#${p}wash)"/>`,pine(120,360,1.9,t.near),pine(1100,362,2,t.near),figure(420,372,1.7,{c:t.ink,hat:'scholar'}),figure(800,370,3.3,{c:t.ink,cloak:true,hat:'top'}),scroll(842,262,70,'#d6c7a0'),lantern(p,870,252,1.1,'#c93b2e'),rain(r,150,.32)].join('')},
