let uid=0;
export function bookScene(bookId,key,{aria=''}={}){
 const t=THEMES[bookId],set=SCENES[bookId];if(!t||!set)return '';
 const s=set[key]||set.intro;const p='b'+(++uid)+'_',r=rngOf(hash(bookId+key));
 const body=s.draw(p,r,t);
 return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${aria.replace(/"/g,'&quot;')}" preserveAspectRatio="xMidYMid slice">${defs(p,t,s.sky)}${sky(p)}${body}${finish(p,t,s.label)}</svg>`;
}
export const chapterKeys=['c1','c2','c3','c4','c5','c6','c7','c8'];
export const sceneLabel=(bookId,key)=>(SCENES[bookId]?.[key]||{}).label||'';

/* ---------- character seals ---------- */
const SEAL_COLORS=['#913e34','#2f6b5c','#5c4a8a','#a8742c','#3b5a82'];
export function charSeal(name,index=0,{size=44,color}={}){
 const raw=String(name||'?').split('·').pop().trim();const cs=[...raw.replace(/\s/g,'')];const label=cs.length>2?cs.slice(0,2):cs;const fill=color||SEAL_COLORS[index%SEAL_COLORS.length];
 const inner=label.length>1?label.map((c,i)=>`<text x="${size/2}" y="${size/2-3+i*16}" font-size="15" text-anchor="middle" fill="#f3e8cc" font-family="'Noto Serif SC','Songti SC',serif" font-weight="600">${c}</text>`).join(''):`<text x="${size/2}" y="${size/2+8}" font-size="24" text-anchor="middle" fill="#f3e8cc" font-family="'Noto Serif SC','Songti SC',serif" font-weight="600">${label[0]}</text>`;
 return `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" aria-hidden="true"><rect x="1" y="1" width="${size-2}" height="${size-2}" rx="6" fill="${fill}"/><rect x="4" y="4" width="${size-8}" height="${size-8}" rx="3" fill="none" stroke="#f3e8cc" stroke-opacity=".45"/>${inner}</svg>`;
}

/* ---------- journey map ---------- */
export function journeyMap(bookId,labels,{current=0,done=false}={}){
 const t=THEMES[bookId],n=labels.length,pts=labels.map((_,i)=>[40+i*(520/(n-1)),46+Math.sin(i*1.3)*16]);
 let d=`M${pts[0][0]} ${pts[0][1]}`;for(let i=1;i<n;i++){const [x0,y0]=pts[i-1],[x1,y1]=pts[i];d+=` C${f(x0+30)} ${f(y0)} ${f(x1-30)} ${f(y1)} ${f(x1)} ${f(y1)}`;}
 return `<svg class="book-map" viewBox="0 0 600 110" role="img" aria-label="旅程地图"><path d="${d}" fill="none" stroke="${t.accent}" stroke-opacity=".35" stroke-width="3" stroke-dasharray="2 7" stroke-linecap="round"/>${pts.map(([x,y],i)=>{const reached=done||i<current,here=!done&&i===current;return `<g>${here?`<circle cx="${x}" cy="${f(y)}" r="16" fill="${t.accent}" opacity=".25"/>`:''}<circle cx="${x}" cy="${f(y)}" r="${here?8:6}" fill="${reached||here?t.accent:'#2a2a30'}" stroke="${here?'#fff':t.accent}" stroke-opacity="${reached||here?1:.4}" stroke-width="1.6"/><text x="${x}" y="${f(y)+(i%2?30:-16)}" font-size="11" text-anchor="middle" fill="${reached||here?'#e9dfc6':'#777'}" font-family="'Noto Serif SC','Songti SC',serif">${labels[i]}</text></g>`;}).join('')}</svg>`;
}
